        need(pl.keep_words([("Thank you.", 0.9, 1.0)], 8.0) == "", "noise at 0.9 was kept")
        need(pl.keep_words([("Thank you.", 0.1, 1.0)], 1.0) == "Thank you.", "a short clear piece was dropped")
